dashboard.definition:
{
  "title": "DNS Analytics",
  "description": "BIND DNS query activity — top clients, record types, beaconing detection, and resolver health",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_queries": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_queries"
      },
      "title": "Total Queries",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_clients": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_clients"
      },
      "title": "Unique Clients",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_beaconing": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_beaconing"
      },
      "title": "Beaconing Domains",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_2nZCdB19": {
      "containerOptions": {},
      "dataSources": {
        "primary": "ds_1ZmrypYh"
      },
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Top 10 Clients - Request Volume",
      "type": "splunk.line"
    },
    "viz_8cdxDtFu": {
      "dataSources": {
        "primary": "ds_yE9yBtpa"
      },
      "options": {
        "backgroundColor": "transparent",
        "bubbleSizeMax": 50,
        "bubbleSizeMethod": "area",
        "bubbleSizeMin": 10,
        "category": "> primary | seriesByIndex(0)",
        "legendDisplay": "right",
        "legendTruncation": "ellipsisMiddle",
        "size": "> primary | seriesByIndex(3)",
        "x": "> primary | seriesByIndex(1)",
        "xAxisAbbreviation": "off",
        "xAxisLabelRotation": 0,
        "xAxisScale": "linear",
        "xAxisTitleVisibility": "hide",
        "y": "> primary | seriesByIndex(2)",
        "yAxisAbbreviation": "auto",
        "yAxisScale": "linear",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "title": "Beaconing Activity",
      "type": "splunk.bubble",
      "showLastUpdated": false,
      "showProgressBar": false
    },
    "viz_JQwHPBuw": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_Kj5JGWVb": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_UBrqm3dh": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_YIm9coVY": {
      "dataSources": {
        "primary": "ds_pYyp9bI7"
      },
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "title": "Requests by Record Type",
      "type": "splunk.line",
      "containerOptions": {},
      "showProgressBar": false,
      "showLastUpdated": false
    },
    "viz_kxbrvLhz": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_mEe7x9fI": {
      "dataSources": {
        "primary": "ds_WaZCTDkV"
      },
      "options": {
        "backgroundColor": "transparent",
        "bubbleSizeMax": 56,
        "bubbleSizeMin": 24,
        "category": "> primary | seriesByName('count')",
        "legendDisplay": "right",
        "legendTruncation": "ellipsisMiddle",
        "size": "> primary | seriesByName('VarianceBeaconTime')",
        "x": "> primary | seriesByName('NumHosts')",
        "xAxisAbbreviation": "off",
        "xAxisLabelRotation": 0,
        "xAxisScale": "linear",
        "xAxisTitleText": "",
        "xAxisTitleVisibility": "hide",
        "y": "> primary | seriesByName('AverageBeaconTime')",
        "yAxisAbbreviation": "auto",
        "yAxisScale": "linear",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      },
      "title": "Hosts to Beaconing Domains",
      "type": "splunk.bubble",
      "showLastUpdated": false,
      "showProgressBar": false
    },
    "viz_yfcE62rT": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_top_domains": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_domains"
      },
      "title": "Top Queried Domains",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_nxdomain": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_nxdomain"
      },
      "title": "Top Clients by Domain Diversity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_query_types": {
      "type": "splunk.pie",
      "dataSources": {
        "primary": "ds_query_types"
      },
      "title": "Query Type Distribution",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "showDonutHole": true,
        "backgroundColor": "transparent"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3m": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_top_resolvers": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_resolvers"
      },
      "title": "Top DNS Resolvers",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/platform/#dns-analytics",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_queries": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_clients": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | eventstats dc(src) as window_dc | timechart span=1d dc(src) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]"
      }
    },
    "ds_kpi_beaconing": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | bucket _time span=1d as day | fields day, _time, query | streamstats current=f last(_time) as last_time by query, day | eval gap=last_time - _time | stats count, avg(gap) AS avg_gap, var(gap) AS var_gap BY query, day | where var_gap < 60 AND count > 2 AND avg_gap > 1 | stats dc(query) as daily by day | rename day as _time | eventstats sum(daily) as total"
      }
    },
    "ds_1ZmrypYh": {
      "name": "top_10_client_search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\"\r\n| timechart span=1h limit=10 usenull=f useother=f count AS Requests by src",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_WaZCTDkV": {
      "name": "hosts_to_beaconing_domains_search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\"\r\n| fields _time, src, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count dc(src) AS NumHosts avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort â€“count\r\n| where VarianceBeaconTime < 60 AND AverageBeaconTime > 0",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_pYyp9bI7": {
      "name": "requests_by_record_type_search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\"\r\n| timechart span=1h usenull=f useother=f count BY record_type",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_yE9yBtpa": {
      "name": "beaconing_activity_search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\"\r\n| fields _time, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort -count\r\n| where VarianceBeaconTime < 60 AND count > 2 AND AverageBeaconTime>1.000\r\n| table  query VarianceBeaconTime  count AverageBeaconTime",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search"
    },
    "ds_top_domains": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | stats count as Queries dc(src) as \"Unique Clients\" by query | sort -Queries | head 20 | rename query as Domain"
      }
    },
    "ds_nxdomain": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | stats count as Queries dc(query) as \"Unique Domains\" by src | eval \"Queries per Domain\"=round(Queries/'Unique Domains', 1) | sort -\"Unique Domains\" | head 20 | rename src as \"Client IP\""
      }
    },
    "ds_query_types": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" record_type=* | stats count by record_type | sort -count"
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_top_resolvers": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` tag=dns message_type=\"Query\" | stats count as Queries, dc(query) as \"Unique Domains\", dc(src) as \"Unique Clients\" by host | sort -Queries | head 20 | rename host as \"Resolver\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "display": "fit-to-width",
          "height": 1321,
          "width": 1920,
          "backgroundColor": "#0d1117"
        },
        "structure": [
          {
            "item": "viz_nav_go",
